using System;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class DxfSourceManager {
 public static int ChooseRemoval(IWin32Window owner,string[] names,int[] affected){if(names.Length==0){MessageBox.Show(owner,"No DXF files are loaded.","DXF files");return -1;}using(var f=new Form{Text="Manage loaded DXF files",ClientSize=new Size(700,420),MinimumSize=new Size(600,400),StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",10)}){var heading=new Label{Text="Select a DXF source to remove",Dock=DockStyle.Top,Height=52,Padding=new Padding(14),Font=new Font("Segoe UI",12,FontStyle.Bold)};var list=new ListBox{Dock=DockStyle.Fill,IntegralHeight=false,BorderStyle=BorderStyle.FixedSingle};foreach(string name in names)list.Items.Add(name);var warning=new Label{Dock=DockStyle.Bottom,Height=75,Padding=new Padding(12),ForeColor=Color.Firebrick};var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=55,Padding=new Padding(8)};var remove=new Button{Text="Remove selected DXF",AutoSize=true};var cancel=new Button{Text="Cancel",AutoSize=true,DialogResult=DialogResult.Cancel};actions.Controls.Add(remove);actions.Controls.Add(cancel);list.SelectedIndexChanged+=(s,e)=>{int n=list.SelectedIndex;warning.Text=n<0?"":affected[n]+" estimate entry/entries use this DXF and will also be removed. Other files and entries will be kept. Save your project first if you need a backup.";};remove.Click+=(s,e)=>{if(list.SelectedIndex<0)return;if(MessageBox.Show(f,"Remove this DXF and its "+affected[list.SelectedIndex]+" linked estimate entry/entries?","Remove source",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)==DialogResult.Yes)f.DialogResult=DialogResult.OK;};f.Controls.Add(list);f.Controls.Add(warning);f.Controls.Add(actions);f.Controls.Add(heading);f.CancelButton=cancel;list.SelectedIndex=0;PowTheme.Apply(f);return f.ShowDialog(owner)==DialogResult.OK?list.SelectedIndex:-1;}}
}
}
